package com.bank.offheap;

import java.lang.foreign.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class OffHeapDemo {
    private static final Logger log = Logger.getLogger(OffHeapDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // try-with-resources on the Arena = deterministic off-heap free. No leak.
        try (var arena = Arena.ofConfined()) {
            var store = new OffHeapPriceStore(arena, 2);  // room for 2 accounts

            // We store balances in paise as longs off-heap (primitive, not objects).
            store.put(0, new BigDecimal("1000000.00"));   // Rajesh SAV2001
            store.put(1, new BigDecimal("250000.00"));    // Priya  CUR3001

            log.info(() -> "Off-heap Rajesh balance: Rs." + store.get(0));
            log.info(() -> "Off-heap Priya  balance: Rs." + store.get(1));

            // Bounds check demo — reading index 2 would throw, not corrupt memory.
            try {
                store.get(2);
            } catch (IndexOutOfBoundsException e) {
                log.warning("Bounds check prevented out-of-range read (safe)");
            }
        } // <-- arena.close() here: ALL off-heap memory freed deterministically

        var writer = new SettlementWriter();
        writer.writeRecord("TRD-0001", new BigDecimal("50000.00"));
        log.info("Settlement record written via direct (zero-copy) buffer");
    }
}

// ─── Would be in store/OffHeapPriceStore.java ───
class OffHeapPriceStore {
    private final MemorySegment segment;   // off-heap, bounds-checked
    private final long capacity;

    OffHeapPriceStore(Arena arena, long capacity) {
        this.capacity = capacity;
        // Allocate capacity * 8 bytes off-heap, owned by the arena.
        this.segment = arena.allocate(capacity * Long.BYTES);
    }

    void put(long index, BigDecimal rupees) {
        if (index < 0 || index >= capacity) throw new IndexOutOfBoundsException("index " + index);
        long paise = rupees.movePointRight(2).longValueExact();  // store as paise long
        segment.setAtIndex(ValueLayout.JAVA_LONG, index, paise);
    }

    BigDecimal get(long index) {
        if (index < 0 || index >= capacity) throw new IndexOutOfBoundsException("index " + index);
        long paise = segment.getAtIndex(ValueLayout.JAVA_LONG, index);
        return BigDecimal.valueOf(paise, 2);  // paise back to rupees with 2 decimals
    }
}

// ─── Would be in io/SettlementWriter.java ───
class SettlementWriter {
    void writeRecord(String tradeId, BigDecimal amount) {
        // Direct buffer: bytes live off-heap, enabling zero-copy socket/file writes.
        java.nio.ByteBuffer buf = java.nio.ByteBuffer.allocateDirect(64);
        buf.put(tradeId.getBytes());
        buf.putLong(amount.movePointRight(2).longValueExact());
        buf.flip();
        // In real code: channel.write(buf) sends straight from off-heap, no copy.
        // The direct buffer's native bytes are freed by a Cleaner when buf is GC'd
        // (non-deterministic) — for hot paths we would POOL buffers, not churn them.
    }
}
